def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_bids = []
    needy_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                needy_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 0.9:
                    aggressive_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        safe = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            safe = DAILY_SALARY * 0.7
        return float(max(0.0, min(budget, safe)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17.0
    loose_supply = supply >= 22.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.88, highest_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.78, avg_prev + 2.0)
    else:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.72, avg_prev + 3.0)
        elif loose_supply:
            bid = DAILY_SALARY * 0.42
        else:
            bid = max(DAILY_SALARY * 0.55, avg_prev + 1.0)

    if len(aggressive_bids) >= 2 and hp > 4 and no_water_days == 0:
        bid *= 0.88

    if needy_count >= 2 and (tight_supply or hp <= 4):
        bid = max(bid, highest_prev + 1.0, DAILY_SALARY * 0.82)

    if day >= 8 and hp > 5 and budget < DAILY_SALARY * 3:
        bid *= 0.9

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 0.15

    max_affordable = max(0.0, budget - reserve_floor)
    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_bid = DAILY_SALARY * 0.7 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] == 3:
        current_bid = max(current_bid, DAILY_SALARY * 0.85)
    elif my_status['hp'] == 4:
        current_bid = max(current_bid, DAILY_SALARY * 0.75)

    if my_status['no_water_days'] > 0:
        current_bid = max(current_bid, DAILY_SALARY * 0.8)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            current_bid = max(current_bid, highest_prev_bid + 5)
        elif highest_prev_bid > current_bid - 20:
             current_bid = max(current_bid, highest_prev_bid + 2)

    day = day_context['day']
    if day >= EPISODE_DAYS - 2:
        current_bid = max(current_bid, DAILY_SALARY * 0.9)
    elif day >= EPISODE_DAYS - 4:
        current_bid = max(current_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_status['budget'], current_bid)

    if final_bid < DAILY_SALARY * 0.1 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    return final_bid

